"""The conformance workflow the resolver renders outside the platform's own tree.

Shared by `test_resolve_project.py` and `test_resolve_conformance_workflow.py`; the text is
pinned here rather than computed, so a render that drifts fails both.
"""

PLATFORM_MARKER = "home/common/agent-skills/platform-manifest.json"
EXPECTED_LOCKED_WORKFLOW = """\
# Generated by resolve-project (project schema 2). Do not edit: the
# Conformance check fails while this file differs from what resolve-project renders.
name: Conformance

on:
  pull_request:
    branches:
      - "main"
  push:
    branches:
      - "main"

permissions:
  contents: read

jobs:
  conformance:
    name: Conformance
    runs-on: ubuntu-24.04
    timeout-minutes: 30
    steps:
      - name: Checkout
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          ref: ${{ github.event.pull_request.head.sha || github.sha }}
      - name: Install Nix
        uses: DeterminateSystems/nix-installer-action@v4
      - name: Run conformance
        run: |
          platform=$(jq -er '.nodes[.nodes[.root].inputs["agent-platform"]].locked | select(.type == "github") | "github:\\(.owner)/\\(.repo)/\\(.rev)"' devenv.lock)
          nix shell "$platform#agent-platform" --command conformance run --purpose ci
"""
